"use client";

import React, { FC, ReactElement, useMemo } from "react";
import {
  sortPaintings,
  getContainerDimensions,
  placePaintings,
  getMaxHeight,
} from "../../functions/arrangePaintings";
import photos from "../../data/gallery.json";
import "../../app/styles/pages/gallery.css";

// The photo list (with sizes) is generated by `npm run gallery`, so the wall can
// be laid out right away and each photo fills in as it downloads.
const GalleryWall: FC = (): ReactElement => {
  const layout = useMemo(() => {
    // The arrangement functions work on objects shaped like element props.
    const paintings = photos.map((photo) => ({
      src: photo.src,
      props: { width: photo.width, height: photo.height, style: { top: 0, left: 0 } },
    }));
    if (paintings.length === 0) return { paintings, width: 0, height: 0 };

    const sorted = sortPaintings(paintings);
    const { width } = getContainerDimensions(sorted);
    placePaintings(sorted, width);
    return { paintings: sorted, width, height: getMaxHeight(sorted) };
  }, []);

  return (
    <div
      className="test-div"
      style={{ width: `${layout.width}px`, height: `${layout.height}px` }}
    >
      {layout.paintings.map(({ src, props }) => (
        <img
          key={src}
          src={src}
          alt="Gallery image"
          className="picture"
          width={props.width}
          height={props.height}
          decoding="async"
          style={{ top: `${props.style.top}px`, left: `${props.style.left}px` }}
        />
      ))}
    </div>
  );
};

export default GalleryWall;
